118	    public OwnerRestControllerV1(ClinicService clinicService,
119	                                 OwnerMapper ownerMapper,
120	                                 PetMapper petMapper,
121	                                 VisitMapper visitMapper,
122	                                 OwnerFieldsValidator ownerFieldsValidator,
123	                                 RegistrationDateValidator registrationDateValidator,
124	                                 RegistrationDateAssigner registrationDateAssigner,
125	                                 MemberIdAssigner memberIdAssigner,
126	                                 IdentityDuplicateChecker identityDuplicateChecker,
127	                                 HouseholdAssigner householdAssigner,
128	                                 HouseholdSizeAssigner householdSizeAssigner,
129	                                 NamesakeCounter namesakeCounter,
130	                                 MembershipLevelAssigner membershipLevelAssigner,
131	                                 CityCapacityChecker cityCapacityChecker,
132	                                 DailyRegistrationLimiter dailyRegistrationLimiter,
133	                                 BulkSignupWarningAssigner bulkSignupWarningAssigner,
134	                                 OwnerCreationAuditLogger ownerCreationAuditLogger,
135	                                 PossibleDuplicateAssigner possibleDuplicateAssigner,
136	                                 IdempotentOwnerStore idempotentOwnerStore,
137	                                 WelcomeNotifier welcomeNotifier) {
138	        this.clinicService = clinicService;
139	        this.ownerMapper = ownerMapper;
140	        this.petMapper = petMapper;
141	        this.visitMapper = visitMapper;
142	        this.ownerFieldsValidator = ownerFieldsValidator;
143	        this.registrationDateValidator = registrationDateValidator;
144	        this.registrationDateAssigner = registrationDateAssigner;
145	        this.memberIdAssigner = memberIdAssigner;
146	        this.identityDuplicateChecker = identityDuplicateChecker;
147	        this.householdAssigner = householdAssigner;
148	        this.householdSizeAssigner = householdSizeAssigner;
149	        this.namesakeCounter = namesakeCounter;
150	        this.membershipLevelAssigner = membershipLevelAssigner;
151	        this.cityCapacityChecker = cityCapacityChecker;
152	        this.dailyRegistrationLimiter = dailyRegistrationLimiter;
153	        this.bulkSignupWarningAssigner = bulkSignupWarningAssigner;
154	        this.ownerCreationAuditLogger = ownerCreationAuditLogger;
155	        this.possibleDuplicateAssigner = possibleDuplicateAssigner;
