165	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
166	    @Override
167	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
168	        Collection<Owner> owners;
169	        if (lastName != null) {
170	            owners = this.clinicService.findOwnerByLastName(lastName);
171	        } else {
172	            owners = this.clinicService.findAllOwners();
173	        }
174	        if (owners.isEmpty()) {
175	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
176	        }
177	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
178	    }
