307	        pet.setId(petId);
308	        visit.setPet(pet);
309	        this.clinicService.saveVisit(visit);
310	        VisitDto visitDto = visitMapper.toVisitDto(visit);
311	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
312	            .buildAndExpand(visit.getId()).toUri());
