            owner.setAddress(line2.isEmpty() ? line1 : line1 + " " + line2);
        } else {
            owner.setAddress(addressNormalizer.normalize(owner.getAddress()));
        }
        if (owner.getAddress() == null || owner.getAddress().isBlank()) {
            errors.rejectValue("address", "required", "must not be blank");
        }
    }

    private void validatePostcode(OwnerFieldsDto owner, Errors errors) {
        String postcode = owner.getPostcode();
        if (postcode == null) {
            return;
        }
        if (!postcodeValidator.isValid(owner.getCity(), postcode)) {
            errors.rejectValue("postcode", "postcode.invalid",
                "must be a valid postcode for the city");
        }
    }

    private void normalizeTelephone(OwnerFieldsDto owner, Errors errors) {
        telephoneNormalizer.toE164(owner.getTelephone()).ifPresentOrElse(
            owner::setTelephone,
